Tool response:
Tool: find_properties
Description: Find properties by name.
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "Property name",
          "title": "Name"
        }
      },
      "required": [
        "name"
      ]
    }

Tool response:
Tool: create_floor_plan
Description: Create a new floor plan for a property.
Parameters:
    {
      "type": "object",
      "properties": {
        "property_id": {
          "type": "integer",
          "title": "Property Id",
          "description": ""
        },
        "name": {
          "type": "string",
          "title": "Name"
        },
        "square_feet": {
          "type": "integer",
          "title": "Square Feet"
        },
        "market_rent": {
          "type": "number",
          "title": "Market Rent"
        }
      },
      "required": [
        "property_id",
        "name",
        "square_feet",
        "market_rent"
      ]
    }

Tool response:
Tool: create_tenant
Description: Create a new tenant record.
Parameters:
    {
      "type": "object",
      "properties": {
        "full_name": {
          "type": "string",
          "title": "Full Name"
        },
