Tool response:
Tool: create_lease
Description: Create a new lease agreement.
Parameters:
    {
      "type": "object",
      "properties": {
        "unit_id": {
          "type": "integer",
          "title": "Unit Id"
        },
        "tenant_id": {
          "type": "integer",
          "title": "Tenant Id"
        },
        "start_date": {
          "type": "string",
          "format": "date",
          "title": "Start Date"
        },
        "end_date": {
          "type": "string",
          "format": "date",
          "title": "End Date"
        },
        "monthly_rent": {
          "type": "number",
          "title": "Monthly Rent"
        },
        "security_deposit": {
          "type": "number",
          "title": "Security Deposit"
        }
      },
      "required": [
        "unit_id",
        "tenant_id",
        "start_date",
        "end_date",
        "monthly_rent",
        "security_deposit"
      ]
    }
